<?php
require_once __DIR__.'/../includes/bootstrap.php';require_admin();$title='Support Centre';$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf(); $action=$_POST['action']??'';
 try{
  if($action==='ticket'){
   $id=(int)$_POST['ticket_id'];$status=in_array($_POST['status']??'OPEN',['OPEN','IN_PROGRESS','RESOLVED','CLOSED'],true)?$_POST['status']:'OPEN';$priority=in_array($_POST['priority']??'NORMAL',['LOW','NORMAL','HIGH'],true)?$_POST['priority']:'NORMAL';$reply=trim((string)($_POST['reply']??''));
   $pdo->prepare('UPDATE support_tickets SET status=?,priority=? WHERE ticket_id=?')->execute([$status,$priority,$id]);
   if($reply!==''){$pdo->prepare("INSERT INTO support_replies(ticket_id,sender_type,sender_id,message) VALUES(?,'ADMIN',?,?)")->execute([$id,(int)$_SESSION['admin_id'],$reply]);$q=$pdo->prepare('SELECT customer_id,subject FROM support_tickets WHERE ticket_id=?');$q->execute([$id]);$t=$q->fetch();if($t)$pdo->prepare('INSERT INTO customer_messages(customer_id,subject,message) VALUES(?,?,?)')->execute([(int)$t['customer_id'],'Support update: '.$t['subject'],$reply]);}
   audit_log('SUPPORT TICKET','ticket_id='.$id.' status='.$status);$msg='Support ticket saved and the customer account was updated.';
  }elseif($action==='announce'){
   $cid=(int)$_POST['customer_id'];$subject=trim((string)$_POST['subject']);$message=trim((string)$_POST['message']);if(!$cid||$subject===''||$message==='')throw new RuntimeException('Customer, subject and message are required.');$pdo->prepare('INSERT INTO customer_messages(customer_id,subject,message) VALUES(?,?,?)')->execute([$cid,$subject,$message]);audit_log('CUSTOMER SUPPORT MESSAGE','customer_id='.$cid);$msg='Web support message delivered to the customer account.';
  }
 }catch(Throwable $e){$err='Support action could not be saved. Please verify the selected record and try again.';}
}
$rows=$pdo->query('SELECT t.*,c.full_name,c.email,c.phone FROM support_tickets t JOIN customers c ON c.customer_id=t.customer_id ORDER BY FIELD(t.status,"OPEN","IN_PROGRESS","RESOLVED","CLOSED"),FIELD(t.priority,"HIGH","NORMAL","LOW"),t.updated_at DESC')->fetchAll();
$customers=$pdo->query('SELECT customer_id,full_name,email,phone FROM customers ORDER BY full_name')->fetchAll();
$open=(int)$pdo->query("SELECT COUNT(*) FROM support_tickets WHERE status IN ('OPEN','IN_PROGRESS')")->fetchColumn();
$unread=(int)$pdo->query("SELECT COUNT(*) FROM customer_private_messages WHERE sender_type='CUSTOMER' AND is_read=0")->fetchColumn();
$supportEmail=store_config_value('support_email','otumas18@gmail.com');$phone=customer_care_phone();$wa=customer_care_whatsapp();
require __DIR__.'/../includes/header.php';
?><div class="admin-layout"><aside class="admin-side"><strong>Management</strong><a href="/admin/dashboard.php">Dashboard</a><a href="/admin/stock.php">Stock</a><a href="/admin/products.php">Products</a><a href="/admin/orders.php">Orders</a><a class="active" href="/admin/support.php">Support</a><a href="/admin/messages.php">Private Chat</a><a href="/admin/analytics.php">Analytics</a><a href="/admin/settings.php">Settings</a><?php if(super_admin()):?><a href="/admin/users.php">Admin & Staff</a><?php endif;?><a href="/admin/system.php">System Health</a></aside>
<section class="admin-main"><div class="section-head"><div><span class="eyebrow">CUSTOMER CARE OPERATIONS</span><h1>Support Centre</h1><p>Contacts, tickets, customer messages and direct support channels are connected to the live database.</p></div></div><?php if($msg):?><div class="flash success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="errors"><?=e($err)?></div><?php endif;?>
<div class="kpi-grid"><div class="stat-card"><span>Open / active tickets</span><strong><?=$open?></strong></div><div class="stat-card"><span>Unread private messages</span><strong><?=$unread?></strong></div><div class="stat-card"><span>Registered customers</span><strong><?=count($customers)?></strong></div><div class="stat-card"><span>Support email</span><strong style="font-size:15px"><?=e($supportEmail)?></strong></div></div>
<section class="support-contact-grid"><article class="panel"><span class="eyebrow">PHONE CONTACT</span><h2>Customer care</h2><p><?=e($phone)?></p><a class="btn primary" href="tel:<?=e($phone)?>">☎ Call customer care</a></article><article class="panel"><span class="eyebrow">WHATSAPP</span><h2>WhatsApp support</h2><p>Direct customer-care channel.</p><a class="btn primary" target="_blank" rel="noopener" href="https://wa.me/<?=e($wa)?>">WhatsApp</a></article><article class="panel"><span class="eyebrow">EMAIL</span><h2>Support inbox</h2><p><?=e($supportEmail)?></p><a class="btn" href="mailto:<?=e($supportEmail)?>">Open email</a></article><article class="panel"><span class="eyebrow">DATABASE MESSAGES</span><h2>Private conversations</h2><p><?=$unread?> unread customer messages.</p><a class="btn" href="/admin/messages.php">Open customer chat</a></article></section>
<section class="panel"><div class="section-head"><div><span class="eyebrow">WEB MESSAGE</span><h2>Send customer support information</h2><p>This writes directly to the customer's account message centre.</p></div></div><form method="post" class="form support-compose"><?=csrf_field()?><input type="hidden" name="action" value="announce"><label>Customer<select name="customer_id" required><option value="">Select customer</option><?php foreach($customers as $c):?><option value="<?=$c['customer_id']?>"><?=e($c['full_name'])?> — <?=e($c['email'])?></option><?php endforeach;?></select></label><label>Subject<input name="subject" maxlength="180" required></label><label>Message<textarea name="message" maxlength="5000" required></textarea></label><button class="btn primary">Send to Customer Account</button></form></section>
<section class="support-list"><div class="section-head"><div><span class="eyebrow">LIVE DATABASE TICKETS</span><h2>Support requests</h2></div></div><?php foreach($rows as $r):?><article class="panel support-ticket"><div class="section-head"><div><span class="eyebrow">TICKET #<?=$r['ticket_id']?></span><h2><?=e($r['subject'])?></h2><p><?=e($r['full_name'])?> · <?=e($r['email'])?> · <?=e($r['phone']??'No phone')?> · <?=e($r['created_at'])?></p></div><span class="status-pill status-<?=strtolower(e($r['status']))?>"><?=e($r['status'])?></span></div><p><?=nl2br(e($r['message']))?></p><div class="support-actions"><a class="btn small" href="tel:<?=e($r['phone']??'')?>">☎ Call</a><?php if(!empty($r['phone'])):?><a class="btn small" target="_blank" rel="noopener" href="https://wa.me/<?=e(preg_replace('/\D+/','',(string)$r['phone']))?>">WhatsApp</a><?php endif;?><a class="btn small" href="mailto:<?=e($r['email'])?>">Email</a><a class="btn small" href="/admin/messages.php?customer_id=<?=$r['customer_id']?>">Private Chat</a></div><form method="post" class="form"><?=csrf_field()?><input type="hidden" name="action" value="ticket"><input type="hidden" name="ticket_id" value="<?=$r['ticket_id']?>"><div class="form-grid"><label>Status<select name="status"><?php foreach(['OPEN','IN_PROGRESS','RESOLVED','CLOSED'] as $st):?><option <?=$st===$r['status']?'selected':''?>><?=$st?></option><?php endforeach;?></select></label><label>Priority<select name="priority"><?php foreach(['HIGH','NORMAL','LOW'] as $st):?><option <?=$st===$r['priority']?'selected':''?>><?=$st?></option><?php endforeach;?></select></label></div><label>Management reply<textarea name="reply" placeholder="Reply to the customer..."></textarea></label><button class="btn primary">Save & Notify</button></form></article><?php endforeach;?><?php if(!$rows):?><div class="empty">No support tickets yet.</div><?php endif;?></section>
</section></div><?php require __DIR__.'/../includes/footer.php';?>
